@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource/dm-mono/400.css";

/* Light (faithful): white page, zinc ink and greys, zinc-50 bands, vermillion brand CTA.
   chart-1 is the green of ratings and "in range" markers. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.21 0.006 285.885);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.21 0.006 285.885);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.21 0.006 285.885);
  --primary: oklch(0.665 0.2 37);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.985 0 0);
  --secondary-foreground: oklch(0.21 0.006 285.885);
  --muted: oklch(0.967 0.001 286.375);
  --muted-foreground: oklch(0.552 0.016 285.938);
  --accent: oklch(0.967 0.001 286.375);
  --accent-foreground: oklch(0.21 0.006 285.885);
  --destructive: oklch(0.6 0.22 20);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.92 0.004 286.32);
  --input: oklch(0.871 0.006 286.286);
  --ring: oklch(0.21 0.006 285.885);
  --highlight: oklch(0.73 0.17 56);
  --highlight-foreground: oklch(0.21 0.006 285.885);
  --glow: oklch(0.73 0.17 56);
  --chart-1: oklch(0.68 0.15 160);
  --chart-2: oklch(0.6 0.12 163);
  --chart-3: oklch(0.85 0.16 100);
  --chart-4: oklch(0.72 0.2 335);
  --chart-5: oklch(0.665 0.2 37);
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.21 0.006 285.885);
  --sidebar-primary: oklch(0.178 0 0);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.967 0.001 286.375);
  --sidebar-accent-foreground: oklch(0.21 0.006 285.885);
  --sidebar-border: oklch(0.92 0.004 286.32);
  --sidebar-ring: oklch(0.705 0.015 286.067);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "DM Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  --radius: 0.75rem;
  --page-width: 78rem;
  --page-gutter: 1.5rem;
  --section-y: 6rem;
}

/* Dark: zinc-950 page, zinc-900 panels, zinc-50 ink; the same vermillion and amber glow. */
.dark {
  --background: oklch(0.141 0.005 285.823);
  --foreground: oklch(0.985 0 0);
  --card: oklch(0.21 0.006 285.885);
  --card-foreground: oklch(0.985 0 0);
  --popover: oklch(0.21 0.006 285.885);
  --popover-foreground: oklch(0.985 0 0);
  --primary: oklch(0.69 0.19 40);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.18 0.006 285.885);
  --secondary-foreground: oklch(0.985 0 0);
  --muted: oklch(0.274 0.006 286.033);
  --muted-foreground: oklch(0.705 0.015 286.067);
  --accent: oklch(0.274 0.006 286.033);
  --accent-foreground: oklch(0.985 0 0);
  --destructive: oklch(0.68 0.2 22);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(1 0 0 / 11%);
  --input: oklch(1 0 0 / 18%);
  --ring: oklch(0.871 0.006 286.286);
  --highlight: oklch(0.76 0.16 60);
  --highlight-foreground: oklch(0.141 0.005 285.823);
  --glow: oklch(0.7 0.17 52);
  --chart-1: oklch(0.72 0.15 160);
  --chart-2: oklch(0.65 0.12 163);
  --chart-3: oklch(0.85 0.15 100);
  --chart-4: oklch(0.75 0.18 335);
  --chart-5: oklch(0.69 0.19 40);
  --sidebar: oklch(0.18 0.006 285.885);
  --sidebar-foreground: oklch(0.985 0 0);
  --sidebar-primary: oklch(0.985 0 0);
  --sidebar-primary-foreground: oklch(0.141 0.005 285.823);
  --sidebar-accent: oklch(0.274 0.006 286.033);
  --sidebar-accent-foreground: oklch(0.985 0 0);
  --sidebar-border: oklch(1 0 0 / 11%);
  --sidebar-ring: oklch(0.552 0.016 285.938);
}
